    {
      "source_id": "kb-handbook",
      "quote": "Skills and certifications are imported per technician, for example gas-safe or backflow-certified, so that jobs are only offered to qualified people.",
      "claim": "Skills-based assignment ensures the right technician goes the first time, reducing repeat visits."
    },
    {
      "source_id": "kb-handbook",
      "quote": "By default the scheduler never books a technician for more than 10 hours in a day and leaves a 15-minute buffer between consecutive jobs; both values can be changed per team.",
      "claim": "Built-in guardrails on daily hours directly address runaway technician overtime."
    },
    {
      "source_id": "kb-pricing-fleet",
      "quote": "Tidewell Dispatch Fleet plan pricing is $64 per technician per month, with a minimum of 75 technicians.",
      "claim": "Fleet plan pricing aligns with the 100k-1m deal size band for a mid-to-large mechanical contractor."
    }
  ],
